  private static void agent(final String agentarg) {
    boolean force = true;
    if (ARG_FORCE.equals(agentarg) || "".equals(agentarg) || null == agentarg) {
      force = true;
    } else if (ARG_OPTIONAL.equals(agentarg)) {
